"""Independent straightforward reference implementation of the replay engine."""
from math import gcd

PS = 10**6


def calib_ref(profile):
    K = profile['groups']; jit = profile['jitter_ps']; ms = profile['measurements']
    INF = float('inf')
    d = [[INF]*K for _ in range(K)]
    for i in range(K):
        d[i][i] = 0
    for (a, b, L, U) in ms:
        d[a][b] = min(d[a][b], U); d[b][a] = min(d[b][a], -L)
    for k in range(K):
        for i in range(K):
            for j in range(K):
                if d[i][k] + d[k][j] < d[i][j]:
                    d[i][j] = d[i][k] + d[k][j]
    feas = all(d[i][i] >= 0 for i in range(K))
    H = [[0]*K for _ in range(K)]; C = [[0]*K for _ in range(K)]
    if feas:
        for a in range(K):
            for b in range(K):
                hi = d[a][b]; lo = -d[b][a]
                H[a][b] = (hi-lo)*500000 + (jit[a]+jit[b])*PS
                C[a][b] = (lo+hi)*500000
    # a feasible bias vector
    x = [0]*K
    if feas and K:
        for v in range(K):
            x[v] = d[0][v]
    return feas, H, C, x


def replay_ref(profile, fb, g, trace):
    feas, H, C, xbias = calib_ref(profile)
    if not feas:
        return None
    N = fb['n']; T = fb['interval_ns']; S = fb['slice_ns']; O = fb['offset_ns']
    slices = fb['slices']; Q = len(slices); P = (Q*S)//gcd(T, Q*S)
    links = fb['links']
    eff = [[fb['drift_ppb'][i]]*P for i in range(N)]
    for (node, a, b, x) in fb['heat']:
        for p in range(a, b):
            eff[node][p] += x
    anch = [[False]*N for _ in range(P)]
    for (node, a, b) in fb['anchors']:
        for p in range(a, b):
            anch[p][node] = True
    black = [[False]*P for _ in range(len(links))]
    for (l, a, b) in fb['blackouts']:
        for p in range(a, b):
            black[l][p] = True
    R = trace['rounds']
    rates = trace['rates_ppb']
