"""JSONL driver for the extended SyncWise computational system.

Reads one JSON request per non-empty stdin line and writes exactly one JSON
response per request, flushed immediately.  Supported ops: calibrate, plan,
audit, replay (see PROTOCOL.md / MODEL.md / CERTIFICATES.md / TRACE.md).
"""
import os
os.environ['OPENBLAS_NUM_THREADS'] = '1'
os.environ['OMP_NUM_THREADS'] = '1'
os.environ['MKL_NUM_THREADS'] = '1'
import json
import sys

sys.setrecursionlimit(200000)

import algo
import para
import simulator


def dispatch(request):
    op = request['op']
    if op == 'calibrate':
        return para.calibrate(request['profile'])
    if op == 'plan':
        return algo.compile_plan(request['profile'], request['fabric'])
    if op == 'audit':
        return algo.audit(request['profile'], request['fabric'], request['proposal'])
    return simulator.run_replay(request['profile'], request['fabric'],
                                request['guard_ns'], request['trace'])


def fallback(request):
    """Keep the response stream aligned even on an unexpected failure."""
    try:
        if request.get('op') == 'audit':
            return {"valid": False}
    except Exception:
        pass
    return {"status": "error"}


def main():
    write = sys.stdout.write
    readline = sys.stdin.readline
    while True:
        line = readline()
        if not line:
            break
        if not line.strip():
            continue
        try:
            request = json.loads(line)
        except Exception:
            continue
        try:
            response = dispatch(request)
            text = json.dumps(response, separators=(',', ':'))
        except Exception:
            try:
                text = json.dumps(fallback(request), separators=(',', ':'))
            except Exception:
                text = '{"status":"error"}'
        write(text)
        write('\n')
        sys.stdout.flush()


